460	/**
461	 * The game port did not open within `GAME_PORT_CHECK_TIMEOUT_MS`. Decide whether
462	 * that means BROKEN or merely SLOW, by asking the guest whether it is still
463	 * doing work, and keep waiting for as long as it is.
464	 *
465	 * Why this exists: the 300s check cannot distinguish "Terraria is sitting on an
466	 * interactive world-selection prompt and will never bind a port" from "ARK is
467	 * 68% through a 22.9 GB SteamCMD download". Both look identical from outside —
468	 * SSH up, game port refused. Before this, both failed the order; measured on
469	 * 2026-09-06, every large Steam-based family was in the second group, so
470	 * healthy servers were being declared failed. Simply raising the timeout would
471	 * fix those at the cost of making genuinely dead servers waste 45 minutes of a
472	 * customer's time before admitting it.
473	 *
474	 * The progress signal is deliberately family-agnostic — no per-image knowledge
475	 * to drift out of date:
476	 *   - the guest's root filesystem is growing (a download/extract is running), OR
477	 *   - the game container has written to its log in the last sample window (world
478	 *     generation, engine startup — work that need not grow the disk much).
479	 * Either counts. `GAME_INSTALL_STALL_LIMIT` consecutive samples with neither is
480	 * what "stopped" means, so a brief pause between download and world-gen phases
481	 * does not end it prematurely.
482	 *
483	 * SAFETY: this runs ONLY after the normal check has already failed, so for every
484	 * family that provisions correctly today this code never executes at all. Any
485	 * error probing the guest returns `ok: false` immediately, i.e. exactly the
486	 * behaviour that existed before — this can only ever turn a failure into a
487	 * success, never the reverse, and `GAME_INSTALL_MAX_WAIT_MS` bounds it absolutely.
488	 */
489	async function waitOutGameInstall(
490	  // Built by the caller from the values IN SCOPE for this provision, not from
491	  // the `server` row it loaded: on a first provision that row still has
492	  // `rootPasswordEnc: null` and `sshPort: null` (both are written to the DB
493	  // *during* this run and the in-memory copy is never refreshed), so
494	  // `serverRootPassword`/`connectionTarget` would resolve to nothing and every
495	  // probe would fail as "the guest stopped answering". Found live 2026-09-06 on
496	  // the first real run of this function.
497	  probeServer: { id: string; rootPassword: string | null; rootPasswordEnc?: string | null; sshPort: number | null; dedicatedIp?: { address: string } | null; node?: { publicIp: string } | null },
498	  checkHost: string,
499	  checkPort: number,
500	  protocol: "tcp" | "udp",
501	  step: (label: string) => Promise<unknown>,
502	  // The game's own systemd unit, so the probe can tell "still installing" from
503	  // "crash-looping". Null for anything with no unit (nothing is judged then).
504	  unitName: string | null,
505	  // Positive in-guest confirmation that the port is really bound — the same one
506	  // the base check uses, so the extended wait cannot end on UDP silence either.
507	  verifyBound: () => Promise<boolean | null>
508	): Promise<{ ok: boolean; reason: string }> {
509	  const deadline = Date.now() + GAME_INSTALL_MAX_WAIT_MS;
510	  let lastUsedKb = -1;
511	  let firstRestarts = -1;
512	  let stalls = 0;
513	  let samples = 0;
514	
515	  // One SSH probe: root-fs used KB, how many bytes the game container has
516	  // logged recently, and how many times its systemd unit has been restarted.
517	  // All plain reads; nothing is mutated on the guest.
518	  const probe = async (): Promise<{ usedKb: number; logBytes: number; restarts: number } | null> => {
519	    try {
520	      return await withServerSsh(probeServer as any, async (conn) => {
521	        const r = await exec(
522	          conn,
523	          `used=$(df --output=used -k / 2>/dev/null | tail -1 | tr -d ' '); ` +
524	            `c=$(docker ps -q 2>/dev/null | head -1); ` +
525	            `lb=0; if [ -n "$c" ]; then lb=$(docker logs --since ${Math.round(GAME_INSTALL_SAMPLE_MS / 1000) + 10}s "$c" 2>&1 | wc -c); fi; ` +
526	            (unitName
527	              ? `nr=$(systemctl show ${unitName} -p NRestarts --value 2>/dev/null); `
528	              : `nr=""; `) +
529	            `case "${"$"}nr" in ''|*[!0-9]*) nr=-1;; esac; ` +
530	            `echo "NXP:${"$"}{used:-0}:${"$"}{lb:-0}:${"$"}nr"`,
531	          QUICK_TIMEOUT_MS
532	        );
533	        const m = /NXP:(\d+):(\d+):(-?\d+)/.exec(r.stdout);
534	        if (!m) return null;
535	        return { usedKb: Number(m[1]), logBytes: Number(m[2]), restarts: Number(m[3]) };
536	      });
537	    } catch {
538	      return null;
539	    }
540	  };
541	
542	  await step("Installing the game — this one is a large download…");
543	
544	  while (Date.now() < deadline) {
545	    const p = await probe();
546	    if (!p) {
547	      return { ok: false, reason: "Could not check whether the install was still running (the guest stopped answering)." };
548	    }
549	    samples++;
550	    if (firstRestarts < 0) firstRestarts = p.restarts;
551	    // A container that keeps dying and being restarted is not installing, and
552	    // its restart output would otherwise read as progress forever — see
553	    // GAME_INSTALL_RESTART_LIMIT. Positive evidence only: an unreadable or
554	    // absent unit reads as -1 and never ends the wait.
555	    if (gameUnitCrashLooping(firstRestarts, p.restarts)) {
556	      return {
557	        ok: false,
558	        reason:
559	          `The game container is crash-looping — its service restarted ${p.restarts - firstRestarts} times ` +
560	          `in ${samples} minute(s) of waiting (systemd NRestarts is now ${p.restarts}), so it was not still installing.`,
561	      };
562	    }
563	    if (lastUsedKb >= 0) {
564	      if (installProgressed({ usedKb: lastUsedKb, logBytes: 0 }, p)) {
565	        stalls = 0;
566	      } else if (++stalls >= GAME_INSTALL_STALL_LIMIT) {
567	        return {
568	          ok: false,
569	          reason:
570	            `The install stopped making progress (${stalls} consecutive minutes with no disk growth and no ` +
571	            `container output, at ${Math.round(p.usedKb / 1024)} MB used), so it was not simply still downloading.`,
572	        };
573	      }
574	    }
575	    lastUsedKb = p.usedKb;
576	
577	    // Waiting and re-checking are the same operation: one sample window of port
578	    // attempts. Returns as soon as the port opens.
579	    const c = await checkGamePortOpen(checkHost, checkPort, protocol, {
580	      timeoutMs: GAME_INSTALL_SAMPLE_MS,
581	      intervalMs: GAME_PORT_CHECK_INTERVAL_MS,
582	      verifyBound,
583	    });
584	    if (c.ok) {
585	      return { ok: true, reason: `still installing for a further ~${samples} min, then the port opened` };
586	    }
587	  }
588	  return {
589	    ok: false,
590	    reason: `It was still installing after ${Math.round(GAME_INSTALL_MAX_WAIT_MS / 60_000)} minutes, which is longer than this platform waits.`,
591	  };
592	}
