594	async function provision(job: Job) {
595	  const server = await loadServer(job);
596	  // Clear any stale failure reason from a previous attempt as this run starts, so
597	  // a successful retry doesn't leave the last error hanging around on the row.
598	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null, provisioningStep: null } });
599	  // Best-effort, human-readable "what's happening right now" label for
600	  // <ProvisioningOverlay/> (lib/provisioning-step.ts) — written between the real,
601	  // observable checkpoints below (Proxmox clone/config/start, guest-agent boot,
602	  // SSH reachability, and the game's own port opening). Never allowed to fail
603	  // the provision — it's purely a display aid, same discipline as worker/hosting.ts's
604	  // equivalent `step()`.
605	  const step = (label: string) =>
606	    db.server.update({ where: { id: server.id }, data: { provisioningStep: label } }).catch(() => undefined);
607	
608	  if (SANDBOX) {
609	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
610	    // resize/start, no OVH allocation, no cloud-init snippet write. `vmid` IS
611	    // still allocated for real (via `allocateSandboxVmid`, see its doc comment
612	    // in lib/ipam.ts) — this used to be the racy inline `990000 +
613	    // (await db.server.count())`, which handed two servers the identical vmid
614	    // whenever no other Server row was created between their two provisioning
615	    // runs (the common case: rows are inserted at checkout, well before the
616	    // PROVISION job runs), and the second `prisma.server.update()` below died
617	    // on the `vmid` unique constraint. Only for a fresh allocation — a retry
618	    // keeps whatever vmid a previous attempt already claimed, same rule the
619	    // real Proxmox path follows just below in the non-sandbox branch.
620	    const vmid = server.vmid ?? (await allocateSandboxVmid(server.id));
621	    const password = generatePassword();
622	    const ip = sandboxIp(vmid);
623	    // Real provisioning writes `step()` between genuinely slow Proxmox
624	    // operations, which is what <Provisioning/> (components/nx/Provisioning.tsx)
625	    // animates through. With nothing real to wait for, this whole function
626	    // used to return in one DB write — so fast that a human watching it never
627	    // saw more than a flash of the spinner before the "server is live" screen,
628	    // which is a real gap for anyone using sandbox mode to see or record the
629	    // deploy flow (lib/provisioning-step.ts's own doc comment already flags
630	    // this: "SANDBOX mode, which completes before any step is ever recorded").
631	    // These are the exact same label substrings <Provisioning/>'s STAGES array
632	    // matches on, staged with real waits so it plays out watchably.
633	    const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
634	    await step("Allocating resources…");
635	    await sleep(1800);
636	    await step("Configuring the network…");
637	    await sleep(1800);
638	    await step("Starting your server…");
639	    await sleep(1800);
640	    await step("Booting the image…");
641	    await sleep(2200);
642	    await step("Waiting for network…");
643	    await sleep(1600);
644	    if (server.gamePlanId) {
645	      await step("Starting the game server…");
646	      await sleep(1600);
647	      await step("Installing the game…");
648	      await sleep(3200);
649	    }
650	    await db.server.update({
651	      where: { id: server.id },
652	      data: { ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
653	    });
654	    await notify(
655	      server.userId,
656	      `Server ${server.hostname} is ready`,
657	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
658	      `/dashboard/servers/${server.id}`
659	    );
660	    // Post-purchase review request (once per server, skipped if no profiles set).
661	    await sendReviewRequestForServer(server.id);
662	    return;
663	  }
664	
665	  const { conn, row: nodeRow } = await nodeFor(server);
666	  const storage = server.plan.storageTier === "hdd"
667	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
668	    : nodeRow?.storageNvme ?? "vmdata";
669	
670	  // Pick a vmid that does NOT still own a previous tenant's backup archives.
671	  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
672	  // server's vzdump archives, so the id freed by a deletion comes back carrying
673	  // the old owner's backups — which every backup surface then attributes to the
674	  // new customer (listBackups/requestRestore key on vmid alone). See
675	  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
676	  // keeps the vmid already persisted on the row.
677	  // The primary's real backup-archive storage predates the storageHdd naming
678	  // convention (it's literally "backup", not "vmdata-hdd") — every node
679	  // onboarded since names its backup-content storage after storageHdd instead.
680	  // See archivedVmids' doc comment in lib/proxmox.ts for the full story.
681	  const backupStorage = nodeRow?.isPrimary ? "backup" : (nodeRow?.storageHdd ?? "backup");
682	  const vmid = server.vmid ?? (await allocateFreshVmid(conn, backupStorage));
683	
684	  // The password must be generated ONCE per VM, not once per attempt. cloud-init's
685	  // cc_set_passwords module is `frequency: once-per-instance` — it applies whatever
686	  // cipassword was baked into the FIRST boot's snippet and never re-applies on a
687	  // later config change unless the guest gets a brand-new instance-id. A retried
688	  // PROVISION (server.vmid already set = the clone below is skipped as
689	  // `vmAlreadyExists`, so the guest never reboots) used to call generatePassword()
690	  // again anyway and overwrite Server.rootPasswordEnc with a value the running VM
691	  // never saw — every later SSH from the platform (control panel, GAME_POWER,
692	  // mods, backups) then authenticated with a password that does not match
693	  // /etc/shadow on the guest, failing with "All configured authentication methods
694	  // failed" (confirmed live on a real customer server: 2 attempts, 0 accepted
695	  // logins ever, until the guest's password was force-resynced via the QGA
696	  // set-user-password path). Reuse the already-stored password whenever this
697	  // server already has a vmid (meaning some earlier attempt may have already
698	  // cloned + booted it); only a truly first attempt mints a new one.
699	  const password = server.vmid ? (serverRootPassword(server) ?? generatePassword()) : generatePassword();
700	
701	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
702	  // VPS: the global `dedicated_ip_default` setting acts as a platform-wide default (included
703	  // on every plan unless the admin switches it off). Game servers: the customer must
704	  // explicitly purchase the addon at checkout — game orders set `wantsDedicatedIp` from the
705	  // intent, so the global default must NOT override it (that was silently granting free IPs).
706	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
707	  const { getSettingBool: _settingBool } = await import("../lib/settings");
708	  const isGame = !!server.gamePlanId;
709	  const wantDedicated = isGame
710	    ? server.wantsDedicatedIp
711	    : server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
712	  if (wantDedicated && (await dedicatedIpProviderConfigured(nodeRow?.id))) {
713	    try {
714	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
715	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
716	      // nodeRow is THIS server's own node — a Hetzner-hosted server draws from
717	      // the Hetzner pool, not whichever pool happens to be configured (the bug
718	      // this replaces: the old `ovhConfigured()`-only gate had no node
719	      // awareness at all).
720	      dedicated = await allocateDedicatedIp(server.id, vmid, nodeRow?.id);
721	      if (!dedicated) {
722	        // allocateDedicatedIp returns null (not a throw) when the node's pool has
723	        // no FREE customer IP to claim — this used to fall through to NAT with
724	        // zero logging, so a customer could be charged for a dedicated IP addon
725	        // at checkout and silently receive a shared NAT address instead, with no
726	        // error, no failed job, and nothing for anyone to notice. Confirmed live:
727	        // node-2 (Hetzner) had an empty pool (0 rows) and a real customer's
728	        // wantsDedicatedIp order fell back to NAT this way.
729	        console.error(
730	          `[worker] dedicated IP requested for server ${server.id} (node ${nodeRow?.id}) but the pool had no FREE address — falling back to NAT. This customer paid for an IP they did not receive.`,
731	        );
732	      }
733	    } catch (e) {
734	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
735	    }
736	  }
737	  // Node-aware + transactionally-claimed allocation (passing the server id enables
738	  // the claim path, so two concurrent provisions can't pick the same IP/port).
739	  let ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
740	  let sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
741	
742	  try {
743	    await db.server.update({
744	      where: { id: server.id },
745	      data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
746	    });
747	  } catch (e: any) {
748	    // Defense in depth: `Server.ipAddress` is UNIQUE and shared between dedicated
749	    // and NAT addresses, so any future desync between the DedicatedIp pool and
750	    // this column (the class of bug fixed in releaseDedicatedIp — see its
751	    // comment) would otherwise crash-loop identically on every PROVISION retry,
752	    // since cleanupFailedProvision() just re-frees the same stuck pool row. If
753	    // we were the one claiming a dedicated IP, self-heal: null it off whichever
754	    // stale server row is still squatting on it, release our own bad claim, and
755	    // fall back to NAT so this customer's server still deploys.
756	    if (dedicated && e?.code === "P2002") {
757	      console.error(`[worker] dedicated IP ${dedicated.address} collided with a stale Server.ipAddress — self-healing and falling back to NAT`, e);
758	      await db.server.updateMany({ where: { ipAddress: dedicated.address }, data: { ipAddress: null, ipv6: null } });
759	      await releaseDedicatedIp(server.id).catch(() => {});
760	      dedicated = null;
761	      ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
762	      sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
763	      await db.server.update({
764	        where: { id: server.id },
765	        data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
766	      });
767	    } else {
768	      throw e;
769	    }
770	  }
771	
772	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
773	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
774	  // (worker restart mid-clone, or any transient failure in the steps below) would
775	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
776	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
777	  // the clone is idempotent, so skip it when the VM is already present.
778	  let vmAlreadyExists = false;
779	  try {
780	    await conn.vmStatus(vmid);
781	    vmAlreadyExists = true;
782	  } catch {
783	    vmAlreadyExists = false;
784	  }
785	  if (vmAlreadyExists) {
786	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
787	  } else {
788	    await step("Allocating your server…");
789	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
790	      newid: vmid,
791	      name: server.hostname,
792	      full: 1,
793	      storage,
794	    });
795	    await conn.waitForTask(cloneUpid, 600_000);
796	  }
797	
798	  // Per-server cloud-init snippet (base + panel/app install + add-ons).
799	  //
800	  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
801	  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
802	  // failed write hands the VM a vendor-data file that does not exist. Root SSH
803	  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
804	  // all silently vanish, and the customer is still told the server is ready.
805	  // Failing here is recoverable — the job retries, and the clone above is
806	  // idempotent. Continuing is not.
807	  // NxCloud hook: if this VM is the backing box for a managed Nextcloud instance,
808	  // generate its one-time admin password (persisted, once) and get the idempotent
809	  // install script to bake into cloud-init. Null for an ordinary VPS.
810	  (server as any).__nxcloudSetup = await nxcloudSetupForServer(server);
811	  // Live telemetry: mint a fresh per-server shipper token and persist its hash
812	  // BEFORE building cloud-init, so the config the agent boots with matches what
813	  // the ingest route will look up (lib/telemetry-token.ts). Re-provisioning
814	  // (this code path runs again) simply mints a new token, invalidating the old
815	  // one — no rotation UI needed for that case.
816	  (server as any).__telemetryToken = await mintServerTelemetryToken(server.id);
817	
818	  await step("Configuring the network…");
