 * Extracted from `buildCloudInit` (2026-09-24) so `gameReinstall` (worker/
 * game-control.ts's GAME_REINSTALL handler) can regenerate the IDENTICAL
 * script an original PROVISION would have used — including reapplying
 * whatever gameVariant/gameConfig the customer has set SINCE the original
 * provision (a reinstall is exactly the moment a setting that silently never
 * applied gets a real chance to take effect), and minting BRAND NEW
 * per-server secrets for palworld/rust/cs2 on every call — the same
 * "reinstall rotates credentials, never keeps the old ones" rule
 * `reinstall()`'s own comment (worker/index.ts) applies to the VPS root
 * password.
 */
export function buildGameSetupScript(server: {
  osTemplate: { setupScript: string | null; family: string | null };
  gameVariant?: string | null;
  gameConfig?: unknown;
}): string | null {
  if (!server.osTemplate.setupScript) return null;
  const scriptWithVariant = applyGameVariant(server.osTemplate.setupScript, server.osTemplate.family, server.gameVariant ?? null);
  const scriptWithConfig = applyGameConfigEnv(
    scriptWithVariant,
    server.osTemplate.family,
    server.gameConfig as Record<string, unknown> | null,
  );
  const scriptWithJavaImage = applyMinecraftJavaImage(
    scriptWithConfig,
    server.osTemplate.family,
    server.gameConfig as Record<string, unknown> | null,
  );
  // dayz (Wave 11, 2026-09-24): shared Nxeon-owned Steam credential, not a
  // freshly-generated per-server secret — see lib/dayz-steam.ts. Unconfigured
  // resolves to an empty object, so applyGameControlSecrets' "only touches a
  // key already present" discipline leaves the setupScript's blank
  // placeholders exactly as seeded (honest SteamCMD anonymous-login failure
  // rather than silently proceeding). lib/game-order.ts also refuses new DayZ
  // orders while unconfigured, so this branch should never actually run
  // against an unconfigured account in production.
  const dayzCreds = dayzSteamCredentials();
  const dayzSecrets: Record<string, string> = dayzCreds ? { USERNAME: dayzCreds.username, PASSWRD: dayzCreds.password } : {};
  const scriptWithSecrets =
    server.osTemplate.family === "palworld"
      ? applyGameControlSecrets(scriptWithJavaImage, { ADMIN_PASSWORD: generatePassword() })
      : server.osTemplate.family === "rust"
        ? applyGameControlSecrets(scriptWithJavaImage, { RUST_RCON_PASSWORD: generatePassword() })
        : server.osTemplate.family === "cs2"
          ? applyGameControlSecrets(scriptWithJavaImage, { CS2_RCONPW: generatePassword() })
          : server.osTemplate.family === "armareforger"
            ? applyGameControlSecrets(scriptWithJavaImage, { ADMIN_PASSWORD: generatePassword() })
            : server.osTemplate.family === "dayz"
              ? applyGameControlSecrets(scriptWithJavaImage, dayzSecrets)
              : scriptWithJavaImage;
  return wrapDockerGameService(scriptWithSecrets, server.osTemplate.family);
}

/**
 * Extract the docker `--name X` container name from a family's RAW (pre-wrap)
 * `docker run -d --name X ...` setupScript — the exact same regex
 * `wrapDockerGameService` above uses, exposed separately for
 * `gameReinstall` (worker/game-control.ts), which needs the real container
 * name to `docker rm -f` the old one before recreating it. Returns null if the
 * script doesn't match that shape (defensive; every current game setupScript
 * does).
 */
export function dockerContainerNameFrom(setupScript: string): string | null {
  const re = /docker run\s+(?:-d|--detach)\b.*?\s+--name[= ]("?)([A-Za-z0-9_.-]+)\1/.exec(setupScript.trim());
  return re ? re[2] : null;
}

/**
 * Extract every `-v hostpath:containerpath` HOST-side path from a family's
 * RAW setupScript — sourced straight from the real `docker run -v ...` flags
 * (never guessed), so these are exactly the directories the game's own
 * container persists data to and the only ones a genuine "wipe" needs to
 * clear. Host paths never contain a colon in any current family's script, so
 * matching up to the first `:` reliably isolates the host side even when the
 * container side is itself quoted-with-spaces (The Isle's setupScript does
 * this: `-v /opt/theisle:"/home/steam/.../The Isle Dedicated Server"`).
 *
 * Safety-guarded, not just parsed: only returns paths that are both
 * `isSafeRemotePath` AND at least two segments under `/opt/` (every real game
 * mount observed in prisma/seed-wave*.ts is `/opt/<family>[/subdir]`) — this
 * is deliberately narrower than `isSafeRemotePath` alone so a malformed or
 * hand-edited OsTemplate row can never make a "wipe" target something as
 * broad as `/`, `/opt`, `/home`, or `/root`.
 */
export function dockerHostMountsFrom(setupScript: string): string[] {
  const out: string[] = [];
  const re = /-v\s+([^\s:]+):/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(setupScript))) {
    const p = m[1];
    if (isSafeRemotePath(p) && /^\/opt\/[A-Za-z0-9_.-]{2,}(\/[A-Za-z0-9_.-]+)*$/.test(p) && !out.includes(p)) {
      out.push(p);
    }
  }
  return out;
}

