/**
 * Skip the Docker CE install when Docker is already on the guest.
 *
 * Every game setupScript starts `curl -fsSL https://get.docker.com | sh && …`.
 * On a stock image that is the install (measured 2026-10-01 on node-5: ~25s
 * including the image pull). On a GOLDEN template (scripts/golden/) Docker is
 * baked in, and on a GAME_REINSTALL the guest already has it — re-running
 * get.docker.com there costs an apt update + a package reinstall (and may
 * restart dockerd under a running container) for nothing. Same exit-status
 * semantics: the group succeeds if Docker exists or the install succeeded.
 */
export function skipDockerInstallIfPresent(setupScript: string): string {
  return setupScript.replace(
    /curl -fsSL https:\/\/get\.docker\.com \| sh(?=\s*&&)/,
    "{ command -v docker >/dev/null 2>&1 || curl -fsSL https://get.docker.com | sh; }"
  );
}

/**
 * Minecraft JVM heap vs the VM's RAM.
 *
 * FOUND 2026-10-01: the catalog hardcodes `-e MEMORY=2G`, and itzg sets BOTH
 * -Xms and -Xmx from it, so on the 2 GB plan the JVM tries to commit the
 * entire VM's RAM as heap before the OS, dockerd and the JVM's own non-heap
 * memory get anything. Reproduced on a clean 2 GB VM with no swap: "There is
 * insufficient memory for the Java Runtime Environment to continue … failed to
 * map 2147483648 bytes", crash loop, NRestarts=78 in 10 minutes. On a real
 * order it only starts because every VM gets a RAM-sized swapfile — i.e. the
 * heap lives partly in swap. The opposite on the 8 GB plan: still 2G heap, so
 * the customer paid for 8 GB and Minecraft could use 2.
 *
 * Rule: leave max(768 MB, 25%) of the VM for the OS + dockerd + JVM non-heap,
 * round down to 256 MB, never below 512 MB. A customer's explicit choice is
 * honoured but clamped to that ceiling; no choice (or the schema default "2G")
 * means "size it to my plan".
 */
export function minecraftMaxHeapMB(ramMB: number): number {
  const headroom = Math.max(768, Math.round(ramMB * 0.25));
  return Math.max(512, Math.floor((ramMB - headroom) / 256) * 256);
}

/** Parse an itzg MEMORY value ("2G", "1536M", "1024m") into MB; null if unparseable. */
export function parseHeapMB(value: unknown): number | null {
  const m = /^\s*(\d+(?:\.\d+)?)\s*([GgMm])\s*$/.exec(String(value ?? ""));
  if (!m) return null;
  const n = Number(m[1]);
  return Math.round(m[2].toLowerCase() === "g" ? n * 1024 : n);
}

export function applyMinecraftHeap(
  setupScript: string,
  family: string | null,
  gameConfig: Record<string, unknown> | null | undefined,
  ramMB: number | null | undefined,
): string {
  if (family !== "minecraft") return setupScript;
  if (!ramMB || !Number.isFinite(ramMB) || ramMB <= 0) return setupScript;
  const re = /-e\s+MEMORY=(?:'[^']*'|"[^"]*"|\S*)/;
  if (!re.test(setupScript)) return setupScript;
  const max = minecraftMaxHeapMB(ramMB);
  const chosenRaw = gameConfig ? gameConfig["MEMORY"] : undefined;
  const chosen = parseHeapMB(chosenRaw);
  const isDefault = chosenRaw === undefined || chosenRaw === null || String(chosenRaw) === "2G";
  const heap = isDefault || chosen === null ? max : Math.min(chosen, max);
  return setupScript.replace(re, `-e MEMORY='${heap}M'`);
}

/**
 * Catalog placeholder values for admin/RCON secrets that are the SAME on every
 * server of a family (prisma/seed-wave*.ts ship `changeme12`; images ship
 * `CHANGEME` / `docker`). Anyone who has read the public seed files — or just
 * guessed — knows them.
 */
export const WEAK_DEFAULT_SECRETS = new Set(["changeme12", "changeme", "CHANGEME", "docker", "admin", "password"]);

/**
 * Admin-/RCON-grade env vars (never join passwords: those are what the
 * customer hands their players, and are left exactly as configured).
 */
export function isAdminSecretEnvKey(envKey: string): boolean {
  if (/^(SERVER_)?(PASSWORD|PASS|PW)$/.test(envKey)) return false; // join password
  if (/CONNECTION|JOIN|WORLD_PASSWORD|GAME_SERVER_PASSWORD|_SERVER_PASSWORD$/.test(envKey)) return false;
  return /(ADMIN|RCON)/.test(envKey) && /(PASS|PW|PASSWRD)/.test(envKey);
}

function scriptEnvValue(script: string, envKey: string): string | null {
  const m = new RegExp(`-e\\s+${envKey}=('[^']*'|"[^"]*"|\\S*)`).exec(script);
  if (!m) return null;
  return m[1].replace(/^['"]|['"]$/g, "");
}

/**
 * Which schema fields of this family are admin/RCON secrets that the customer
 * left blank AND whose catalog placeholder is a weak shared default — i.e. the
 * server would otherwise boot with the same admin password as every other
 * server of that family. Returns schema FIELD keys; the caller (provision())
 * mints a value for each and persists it into Server.gameConfig, so it is
 * (a) substituted by applyGameConfigEnv like any customer value, (b) visible to
 * the customer in Settings, and (c) stable across PROVISION retries and
 * GAME_REINSTALL. Platform RCON is unaffected: it reads the password back out
 * of the running container's env (lib/game-control.ts `docker-env`).
 *
 * Found 2026-10-01: e.g. Project Zomboid shipped `ADMIN_USERNAME=admin
 * ADMIN_PASSWORD=changeme12` — anyone joining could log in as server admin —
 * and ARK/ARK SA/Icarus/Soulmask/L4D2/TF2 ship the same `changeme12` for their
 * admin/RCON password.
 */
export function adminSecretFieldsToMint(
  family: string | null,
  rawSetupScript: string | null,
  gameConfig: Record<string, unknown> | null | undefined,
): string[] {
  if (!family || !rawSetupScript) return [];
  const schema = schemaFor(family);
  if (!schema) return [];
  const out: string[] = [];
  for (const f of schema.fields) {
    if (f.type !== "string") continue;
    const envKey = f.envKey ?? f.key;
    if (!isAdminSecretEnvKey(envKey)) continue;
    const current = scriptEnvValue(rawSetupScript, envKey);
    if (current === null || !WEAK_DEFAULT_SECRETS.has(current)) continue;
    const chosen = gameConfig ? gameConfig[f.key] : undefined;
    if (chosen !== undefined && chosen !== null && String(chosen).trim() !== "" && !WEAK_DEFAULT_SECRETS.has(String(chosen))) continue;
    out.push(f.key);
  }
  return out;
}

/**
 * Backstop for admin/RCON env vars with NO schema field (so nothing can be
 * persisted for the customer): if the final script still carries a weak shared
 * default, replace it with a fresh per-server value. Same rotate-per-build
 * rule as Palworld/Rust/CS2 above.
 */
export function rotateWeakAdminSecrets(setupScript: string): string {
  let out = setupScript;
  const re = /-e\s+([A-Z0-9_]+)=('[^']*'|"[^"]*"|\S*)/g;
  const keys = new Set<string>();
  let m: RegExpExecArray | null;
  while ((m = re.exec(setupScript))) {
    const value = m[2].replace(/^['"]|['"]$/g, "");
    if (isAdminSecretEnvKey(m[1]) && WEAK_DEFAULT_SECRETS.has(value)) keys.add(m[1]);
  }
  if (keys.size === 0) return out;
  const secrets: Record<string, string> = {};
  for (const k of keys) secrets[k] = generatePassword();
  out = applyGameControlSecrets(out, secrets);
  return out;
}

/** Mint one per-server secret (exported so provision() uses the same generator). */
export function mintGameSecret(): string {
  return generatePassword();
}

