test("joinPortFor defaults to GAME_PORT for families with no override", () => {
  // A representative spread of families whose check port IS the join port.
  for (const fam of ["minecraft", "palworld", "valheim", "terraria", "bedrock", "eco", "soulmask", "nightingale"] as const) {
    assert.deepEqual(joinPortFor(fam), GAME_PORT[fam], `${fam} should have no join-port override`);
  }
});

test("the RCON/query-port families join on a DIFFERENT port than GAME_PORT", () => {
  // Each of these has GAME_PORT pointing at an RCON/query/admin port on purpose
  // (it is TCP, so a plain connect is real evidence the game bound it). Their
  // join ports come from the same `docker run -p ...` mappings GAME_PORT does.
  const expected = {
    rust: { port: 28015, protocol: "udp" },
    ark: { port: 7777, protocol: "udp" },
    projectzomboid: { port: 16261, protocol: "udp" },
