import { test } from "node:test";
import assert from "node:assert/strict";
import { guestAgentProbePath, waitForGuestAgent, freshVmidFloor, isReservedVmid } from "../lib/proxmox.ts";
import { chooseCloneSource, goldenTemplateVmidFromEnv, diskSizeGBFromSpec } from "../lib/golden-template.ts";
import { cloudInitPackagesBlock, SETUP_RUNCMD } from "../worker/cloud-init-parts.ts";
import {
  skipDockerInstallIfPresent,
  applyMinecraftHeap,
  minecraftMaxHeapMB,
  parseHeapMB,
  adminSecretFieldsToMint,
  rotateWeakAdminSecrets,
  isAdminSecretEnvKey,
  buildGameSetupScript,
} from "../worker/game-variant.ts";
import { templateVmidsFromListing, nodesWithTemplate } from "../lib/node-templates.ts";

// ---------------------------------------------------------------------------
// Guest-agent readiness probe (the fixed 180s wait on every provision)
// ---------------------------------------------------------------------------

test("guest-agent probe never uses agent/ping (Proxmox has no GET handler for it)", () => {
  const p = guestAgentProbePath("nxeon-bhs1", 139);
  assert.equal(p, "/nodes/nxeon-bhs1/qemu/139/agent/info");
  assert.doesNotMatch(p, /\/ping$/);
});

test("waitForGuestAgent returns true on the first answering GET, without waiting out its timeout", async () => {
  const calls: string[] = [];
  const client = {
    get: async (path: string) => {
      calls.push(path);
      if (path.endsWith("/agent/ping")) throw new Error("No 'get' handler defined");
      return { result: { version: "8.2.2" } };
    },
  };
  const t0 = Date.now();
  assert.equal(await waitForGuestAgent(client, "n", 1, 5_000, 10), true);
  assert.ok(Date.now() - t0 < 1_000);
  assert.deepEqual(calls, ["/nodes/n/qemu/1/agent/info"]);
});

// ---------------------------------------------------------------------------
// Never-reuse vmid floor
// ---------------------------------------------------------------------------

test("freshVmidFloor starts above every vmid ever handed out, not at nextid's lowest-free", () => {
  // nextid offers 117 (a just-destroyed server's id); rows exist up to 600.
  assert.equal(freshVmidFloor(117, [100, 117 - 1, 600]), 601);
  // nextid already higher than anything used: keep it.
  assert.equal(freshVmidFloor(700, [100, 600]), 700);
});

test("freshVmidFloor ignores template-range and sandbox ids, and never lands in 9000-9999 or a reserved id", () => {
  assert.equal(freshVmidFloor(100, [9000, 9101, 990005]), 100);
  assert.equal(freshVmidFloor(100, [8999]), 10000);
  assert.equal(freshVmidFloor(9000, []), 10000);
  assert.equal(freshVmidFloor(200, []), 201);
  assert.equal(freshVmidFloor(100, [7999]), 8001);
  assert.ok(isReservedVmid(9101) && isReservedVmid(200) && isReservedVmid(8000) && !isReservedVmid(601));
});

// ---------------------------------------------------------------------------
// Golden template selection
// ---------------------------------------------------------------------------

const goldenCfg = { template: 1, tags: "nxeon-golden", scsi0: "vmdata:base-9101-disk-0,discard=on,size=12G" };

test("goldenTemplateVmidFromEnv: bare id, per-family map, wildcard, and junk", () => {
  assert.equal(goldenTemplateVmidFromEnv(undefined, "minecraft"), null);
  assert.equal(goldenTemplateVmidFromEnv("9101", "rust"), 9101);
  assert.equal(goldenTemplateVmidFromEnv("minecraft:9101,valheim:9101", "minecraft"), 9101);
  assert.equal(goldenTemplateVmidFromEnv("minecraft:9101,valheim:9101", "rust"), null);
  assert.equal(goldenTemplateVmidFromEnv("minecraft:9101,*:9102", "rust"), 9102);
  assert.equal(goldenTemplateVmidFromEnv("9000", "minecraft"), null, "stock templates are not golden");
  assert.equal(goldenTemplateVmidFromEnv("minecraft:abc", "minecraft"), null);
});

test("diskSizeGBFromSpec reads G and M sizes", () => {
  assert.equal(diskSizeGBFromSpec(goldenCfg.scsi0), 12);
  assert.equal(diskSizeGBFromSpec("vmdata:base-9000-disk-0,discard=on,size=3584M"), 3.5);
  assert.equal(diskSizeGBFromSpec("vmdata:x"), null);
});

test("chooseCloneSource uses the golden template only when every guard passes", () => {
  const base = { baseVmid: 9000, isGame: true, goldenVmid: 9101, nodeConfig: goldenCfg, targetDiskGB: 20 };
  assert.deepEqual(chooseCloneSource(base).vmid, 9101);
  assert.equal(chooseCloneSource(base).golden, true);
  assert.equal(chooseCloneSource({ ...base, goldenVmid: null }).vmid, 9000);
  assert.equal(chooseCloneSource({ ...base, isGame: false }).vmid, 9000);
  assert.equal(chooseCloneSource({ ...base, baseVmid: 9001 }).vmid, 9001);
  assert.equal(chooseCloneSource({ ...base, nodeConfig: null }).vmid, 9000, "node without the golden template");
  assert.equal(chooseCloneSource({ ...base, nodeConfig: { ...goldenCfg, template: 0 } }).vmid, 9000);
  assert.equal(chooseCloneSource({ ...base, nodeConfig: { ...goldenCfg, tags: "other" } }).vmid, 9000);
  assert.equal(chooseCloneSource({ ...base, targetDiskGB: 5 }).vmid, 9000, "golden disk bigger than the order (cannot shrink)");
});

// ---------------------------------------------------------------------------
// Cloud-init
// ---------------------------------------------------------------------------

test("cloud-init package block: unchanged on stock images, omitted on golden clones", () => {
  const stock = cloudInitPackagesBlock(false);
  assert.match(stock, /^package_update: true\npackages:\n  - qemu-guest-agent\n  - unzip\n$/);
  assert.equal(cloudInitPackagesBlock(true), "");
});

test("the setup log is created 0600 before the set -x script writes secrets into it", () => {
  const lines = SETUP_RUNCMD.split("\n");
  assert.match(lines[0], /install -m 600 \/dev\/null \/var\/log\/nxeon-setup\.log/);
  assert.match(lines[1], />> \/var\/log\/nxeon-setup\.log 2>&1 &$/);
});

// ---------------------------------------------------------------------------
// Game setup scripts
// ---------------------------------------------------------------------------

const MC =
  "curl -fsSL https://get.docker.com | sh && docker run -d --name mc -e EULA=TRUE -e MEMORY=2G -e VERSION='1.21.1' -p 25565:25565 -p 25575:25575 -v /opt/mc:/data --restart unless-stopped itzg/minecraft-server:java21";

test("skipDockerInstallIfPresent keeps the && chain and only installs Docker when absent", () => {
  const out = skipDockerInstallIfPresent(MC);
  assert.ok(out.startsWith("{ command -v docker >/dev/null 2>&1 || curl -fsSL https://get.docker.com | sh; } && docker run -d --name mc"));
  assert.equal(skipDockerInstallIfPresent("echo hi"), "echo hi");
});

test("minecraftMaxHeapMB leaves OS + JVM headroom", () => {
  assert.equal(minecraftMaxHeapMB(2048), 1280);
  assert.equal(minecraftMaxHeapMB(4096), 3072);
  assert.equal(minecraftMaxHeapMB(8192), 6144);
  assert.equal(minecraftMaxHeapMB(1024), 512);
  assert.equal(parseHeapMB("2G"), 2048);
  assert.equal(parseHeapMB("1536M"), 1536);
  assert.equal(parseHeapMB("lots"), null);
});

test("applyMinecraftHeap sizes the default to the plan and clamps an explicit choice", () => {
  assert.match(applyMinecraftHeap(MC, "minecraft", null, 2048), /-e MEMORY='1280M'/);
  assert.match(applyMinecraftHeap(MC, "minecraft", { MEMORY: "2G" }, 8192), /-e MEMORY='6144M'/);
  assert.match(applyMinecraftHeap(MC, "minecraft", { MEMORY: "8G" }, 4096), /-e MEMORY='3072M'/);
  assert.match(applyMinecraftHeap(MC, "minecraft", { MEMORY: "1G" }, 4096), /-e MEMORY='1024M'/);
