  assert.equal(goldenTemplateVmidFromEnv("minecraft:9101,valheim:9101", "rust"), null);
  assert.equal(goldenTemplateVmidFromEnv("minecraft:9101,*:9102", "rust"), 9102);
  assert.equal(goldenTemplateVmidFromEnv("9000", "minecraft"), null, "stock templates are not golden");
